INSERT INTO ANALYSE (ID_DOCUMENT, NUM_ANALYSE, PM, AM1, AM2, AM3, AM4, AM5, AM6, AM7, AM8, AM9, AM10, AM11, AM12, SOMMAIRE, TITRE_REFERENCE) VALUES (${SOURCEID}, 1, 'ACTION CIVILE*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Une indemnité d''occupation prononcée à la suite de la résiliation d''un contrat de bail par la juridiction civile contre l''occupant d''un local qui s''est maintenu dans les lieux ne saurait être considérée comme de nature contractuelle dès lors qu''elle sanctionne une occupation des lieux sans droit ni titre, constitutive d''une faute civile au sens de l''article 1240 du code civil et qu''elle n''a pas sa cause dans ledit contrat de bail.\n\nC''est à bon droit qu''une cour d''appel déclare coupable du délit d''organisation frauduleuse d''insolvabilité prévu par l''article 314-7 du code pénal le prévenu qui a pris des dispositions pour faire échapper sa société au paiement d''une somme correspondant à une indemnité d''occupation, dont les juges retiennent qu''elle est de nature quasi-délictuelle', NULL);